#Requires -Version 5.1
# fix-planificador-columna-obra-optimizacion.ps1
#
# IMPLEMENTACION (solo cambios visuales/maquetacion, ninguna logica funcional):
#
# 1. src/app/planificacion/page.tsx (MODIFICADO)
#
#    a) Nombre + estado de la obra (ObraRow)
#       - El nombre ahora usa line-clamp-2 (maximo 2 lineas, con elipsis si
#         no cabe) en vez de truncate a una sola linea. title=obra.nombre
#         para ver el nombre completo en tooltip al pasar el raton.
#       - El estado (select) se mantiene compacto: shrink-0, max-w-[86px],
#         truncate, whitespace-nowrap, texto mas pequeno (text-[9px]),
#         mismo color configurado en estados_obra via style={{color:...}}.
#       - La fila crece de alto SOLO cuando el nombre necesita 2 lineas
#         (flexbox stretch); en el caso normal (nombre corto) la fila sigue
#         tan compacta como antes.
#
#    b) Columna Obra/Persona redimensionable (Excel-like)
#       - Nueva constante LABEL_W_DEFAULT=210, LABEL_W_MIN=140,
#         LABEL_W_MAX=420, persistida en localStorage
#         (obrasplan_planificador_label_w).
#       - Nuevo estado labelW sustituye a la constante fija LABEL_W en
#         TODOS sus usos: cabecera, SinAsignarRow, ObraRow y
#         SortablePersonRow (Vista Obras y Vista Personas comparten la
#         misma columna redimensionable).
#       - Controlador de redimensionado (role=separator) dentro de la
#         cabecera sticky, en el limite exacto entre la columna Obra y el
#         primer dia. cursor-col-resize, arrastre en tiempo real
#         (mousedown/mousemove/mouseup con limites min/max), doble clic
#         restaura la anchura por defecto. Al terminar el arrastre se
#         guarda en localStorage.
#       - Es un div independiente SIN listeners de dnd-kit: no puede
#         activar el drag & drop de recursos ni la reordenacion de obras
#         (verificado, ver mensaje del asistente).
#       - Las columnas de los dias mantienen su anchura actual (dw, sin
#         cambios).
#
#    c) Circulos de RRHH dentro de las celdas (ObraCell y SinAsignarRow)
#       - Vista semana/mes (dw>60): 24px (w-6 h-6) -> 20px (w-5 h-5),
#         iniciales 8px -> 7px.
#       - Vista año (dw<=60): 16px (w-4 h-4) -> 14px (w-3.5 h-3.5),
#         iniciales 6px -> 5.5px.
#       - Anillos de conflicto (ring-2 ring-red-400) sin cambios.
#       - Iconos de vehiculos/otros recursos SIN modificar (fuera de
#         alcance: la peticion es especifica de circulos de RRHH).
#
# NO SE HA MODIFICADO NINGUNA LOGICA FUNCIONAL:
#   drag & drop, reordenacion de obras, asignaciones, permisos, filtros,
#   navegacion semanal, Vista Personas, vista movil, fila SIN ASIGNAR,
#   resaltado de fila/columna/celda/dia actual, iconos de vehiculos,
#   documentos o notas. Verificado via diff filtrando por handlers,
#   useSortable/useDroppable/useDraggable, checkRrhhDisponibilidad y
#   llamadas a supabase.
#
# AUDIT LOG: no aplica (cambio puramente visual, no toca tablas, endpoints
# ni formularios nuevos).
#
# EJECUCION: no requiere migracion SQL ni pasos manuales en Supabase.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR: no se encuentra $RepoPath" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> fix: optimizar columna Obra (nombre 2 lineas, estado compacto, columna redimensionable, circulos RRHH mas pequenos)" -ForegroundColor Cyan

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 81 KB" -ForegroundColor Green

$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
if ($page.Contains('line-clamp-2'))                          { Write-Host "  OK: nombre de obra con line-clamp-2" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('LABEL_W_DEFAULT') -and $page.Contains('LABEL_W_STORAGE_KEY')) { Write-Host "  OK: columna Obra redimensionable con persistencia" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('handleLabelResizeStart') -and $page.Contains('handleLabelResizeReset')) { Write-Host "  OK: arrastre + doble clic para restaurar" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('cursor-col-resize'))                     { Write-Host "  OK: cursor col-resize en el controlador" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('dw > 60 ? "w-5 h-5" : "w-3.5 h-3.5"'))   { Write-Host "  OK: circulos RRHH reducidos en ObraCell" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if (-not $page.Contains('const LABEL_W = 210'))               { Write-Host "  OK: constante fija LABEL_W eliminada (ahora dinamica)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  No requiere migracion SQL ni pasos manuales en Supabase." -ForegroundColor Yellow
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: optimizar columna Obra del planificador (nombre 2 lineas, columna redimensionable, circulos RRHH mas pequenos)"'
Write-Host "  git push"
Write-Host ""
Write-Host "  Despues del deploy: Vercel -> Deployments -> ... -> Promote to Production" -ForegroundColor Yellow
